"""Installs the finished web app (v0.6): 3D + printable design page, Regional page, clean charts, tests.
Run once from the src folder:   python install_v06.py
Your current files are first copied to backup_v05, so nothing is lost.
README.md, THIRD_PARTY.md and .gitignore go in the folder above src (the repo root)."""
import os, shutil
FILES = {
    'app.py': '"""\nIntze Tank Platform -- web app (stage 1: login, roles, project overview,\nsite desk, advice).\n\nRun from the src folder:   python app.py      then open http://127.0.0.1:5000\n\nROLES (checked on the SERVER for every action, not just hidden in menus):\n  manager  Project Manager / Design Engineer -- everything, including site\n           data, cost cap and approving a changed plan.\n  site     Site Engineer -- logs progress and concrete stock, sees advice,\n           CANNOT change site data / cost cap or approve a changed plan.\n  client   Client / Viewer -- read-only.\n\nDEMO ACCOUNTS ONLY: the three passwords below are for demonstration and\nmust be replaced (and the SECRET_KEY set) before any real deployment.\nThe project data is the same project_state.json the command-line tracker uses.\n"""\n\nimport io\nimport json\nimport os\nimport secrets\nfrom contextlib import redirect_stdout\nfrom functools import wraps\n\nfrom flask import (Flask, abort, flash, g, redirect, render_template, request,\n                   send_file, session, url_for)\nfrom werkzeug.security import check_password_hash, generate_password_hash\n\nimport construction_tracker as ct\nimport optimizer as opt\nimport regional_planner as rp\nimport visualize_tank as vt\nfrom cost_model import total_relative_cost\nfrom intze_design_engine import design_intze_tank\nfrom models import DesignInputs\n\napp = Flask(__name__)\napp.secret_key = os.environ.get("INTZE_SECRET_KEY", "demo-only-change-me")\n\nROLE_LABEL = {"manager": "Project Manager", "site": "Site Engineer", "client": "Client"}\nROLE_CAN = {\n    "manager": {"view", "log", "site_data", "approve", "start"},\n    "site": {"view", "log"},\n    "client": {"view"},\n}\n\nUSERS = {\n    "manager": {"name": "Project Manager", "role": "manager",\n                "hash": generate_password_hash("Manager@123")},\n    "site": {"name": "Site Engineer", "role": "site",\n             "hash": generate_password_hash("Site@123")},\n    "client": {"name": "Client", "role": "client",\n               "hash": generate_password_hash("Client@123")},\n}\n\nSTAGE_LABEL = {\n    "foundation": "Foundation", "staging": "Staging columns",\n    "container_bottom": "Container bottom", "wall": "Cylindrical wall",\n    "top_dome": "Top dome", "finishing": "Finishing",\n}\n\n\n# ------------------------------------------------------------ helpers\ndef project_exists():\n    return os.path.exists(ct.STATE_FILE)\n\n\ndef get_state():\n    with open(ct.STATE_FILE) as f:\n        return json.load(f)\n\n\ndef csrf_token():\n    if "csrf" not in session:\n        session["csrf"] = secrets.token_hex(16)\n    return session["csrf"]\n\n\napp.jinja_env.globals["csrf_token"] = csrf_token\napp.jinja_env.globals["STAGE_LABEL"] = STAGE_LABEL\n\n\n@app.before_request\ndef load_user():\n    g.user = None\n    uname = session.get("user")\n    if uname in USERS:\n        g.user = {"username": uname, **USERS[uname]}\n    if request.method == "POST":\n        if request.form.get("csrf") != session.get("csrf"):\n            abort(400)\n\n\n@app.context_processor\ndef inject():\n    can = ROLE_CAN.get(g.user["role"], set()) if g.user else set()\n    return {"user": g.user, "can": can, "role_label": ROLE_LABEL}\n\n\ndef need(permission):\n    def deco(fn):\n        @wraps(fn)\n        def wrapper(*a, **kw):\n            if not g.user:\n                return redirect(url_for("login"))\n            if permission not in ROLE_CAN[g.user["role"]]:\n                abort(403)\n            return fn(*a, **kw)\n        return wrapper\n    return deco\n\n\ndef quiet(fn, *a, **kw):\n    """Run a tracker function that prints; keep its output out of the server console."""\n    with redirect_stdout(io.StringIO()):\n        return fn(*a, **kw)\n\n\ndef by(text):\n    return f"{text} (by {ROLE_LABEL[g.user[\'role\']]})"\n\n\n# ------------------------------------------------------------ auth\n@app.route("/login", methods=["GET", "POST"])\ndef login():\n    if g.user:\n        return redirect(url_for("overview"))\n    if request.method == "POST":\n        u = USERS.get(request.form.get("username", "").strip().lower())\n        if u and check_password_hash(u["hash"], request.form.get("password", "")):\n            session.clear()\n            session["user"] = request.form["username"].strip().lower()\n            return redirect(url_for("overview"))\n        flash("That username and password do not match. Check both and try again.", "error")\n    return render_template("login.html")\n\n\n@app.route("/logout", methods=["POST"])\ndef logout():\n    session.clear()\n    return redirect(url_for("login"))\n\n\n@app.route("/")\ndef home():\n    return redirect(url_for("overview"))\n\n\n# ------------------------------------------------------------ pages\n@app.route("/overview")\n@need("view")\ndef overview():\n    if not project_exists():\n        return render_template("empty.html", page="overview")\n    st = get_state()\n    return render_template(\n        "overview.html", page="overview", st=st,\n        pct=ct.overall_progress(st), weights=ct.STAGE_WEIGHTS,\n        locked=ct.locked_columns(st), recent=list(reversed(st["log"]))[:8])\n\n\n@app.route("/site-desk")\n@need("log")\ndef site_desk():\n    if not project_exists():\n        return render_template("empty.html", page="site")\n    st = get_state()\n    return render_template("site_desk.html", page="site", st=st,\n                           grades=ct.GRADES, weights=ct.STAGE_WEIGHTS)\n\n\nDESIGN_LIMITS = {\n    "capacity_kl": (50, 2000, "Capacity (kL)"),\n    "staging_height_m": (6, 30, "Staging height (m)"),\n    "soil_bearing_kpa": (50, 500, "Soil bearing (kPa)"),\n    "wind_speed_m_s": (30, 60, "Basic wind speed (m/s)"),\n    "seismic_zone_factor": (0.05, 0.40, "Seismic zone factor"),\n}\n\n\n@app.route("/design", methods=["GET", "POST"])\n@need("view")\ndef design():\n    form = {"capacity_kl": 500, "staging_height_m": 16, "soil_bearing_kpa": 150,\n            "wind_speed_m_s": 44, "seismic_zone_factor": 0.16}\n    results = None\n    dropped = 0\n    if request.method == "POST":\n        vals = {}\n        for key, (lo, hi, label) in DESIGN_LIMITS.items():\n            raw = request.form.get(key, "").strip()\n            form[key] = raw\n            try:\n                v = float(raw)\n            except ValueError:\n                flash(f"{label}: enter a number.", "error")\n                return render_template("design.html", page="design", form=form,\n                                       results=None, dropped=0, limits=DESIGN_LIMITS)\n            if not lo <= v <= hi:\n                flash(f"{label} must be between {lo} and {hi}.", "error")\n                return render_template("design.html", page="design", form=form,\n                                       results=None, dropped=0, limits=DESIGN_LIMITS)\n            vals[key] = v\n        site = {"capacity_liters": vals["capacity_kl"] * 1000,\n                "staging_height_m": vals["staging_height_m"],\n                "soil_bearing_kpa": vals["soil_bearing_kpa"],\n                "wind_speed_m_s": vals["wind_speed_m_s"],\n                "seismic_zone_factor": vals["seismic_zone_factor"]}\n        try:\n            cands = quiet(opt.run_optimization, site)\n            results, dropped = quiet(opt.refine_with_real_engine, cands, site)\n        except Exception:\n            flash("The design could not be computed for these inputs. Check them and try again.", "error")\n    return render_template("design.html", page="design", form=form, results=results,\n                           dropped=dropped, limits=DESIGN_LIMITS)\n\n\n# ------------------------------------------------------------ vendor script (not stored in the project)\n@app.route("/vendor/plotly.js")\n@need("view")\ndef vendor_plotly():\n    """Serves the Plotly.js file from the installed plotly package, so the pages\n    work offline and the project repository does not contain a copy of the library."""\n    import plotly\n    path = os.path.join(os.path.dirname(plotly.__file__), "package_data", "plotly.min.js")\n    if not os.path.exists(path):\n        abort(404)\n    return send_file(path, mimetype="application/javascript", max_age=86400)\n\n\n# ------------------------------------------------------------ design detail (3D + printable summary)\nOUTPUT_ROWS = [\n    ("Geometry", [\n        ("Internal diameter", "internal_diameter_m", "m"), ("Cylinder height (with free board)", "cylindrical_wall_height_m", "m"),\n        ("Water held (cylinder + cone + bottom dome)", "actual_water_volume_m3", "m³"),\n        ("Cone bottom diameter", "cone_bottom_diameter_m", "m"), ("Cone slant height", "cone_slant_height_m", "m"),\n        ("Top dome rise", "top_dome_rise_m", "m"), ("Bottom dome rise", "bottom_dome_rise_m", "m")]),\n    ("Shell members", [\n        ("Wall thickness", "cylindrical_wall_thickness_mm", "mm"), ("Hoop steel in wall", "cylindrical_wall_hoop_steel_mm2_per_m", "mm² per m"),\n        ("Top dome thickness", "top_dome_thickness_mm", "mm"), ("Bottom dome thickness", "bottom_dome_thickness_mm", "mm"),\n        ("Ring beam tension (simplified)", "ring_beam_hoop_tension_kn", "kN"), ("Ring beam size", None, "mm")]),\n    ("Staging and foundation", [\n        ("Column diameter (at base)", "staging_column_diameter_mm", "mm"), ("Bracing tiers", "staging_num_bracing_tiers", ""),\n        ("Governing lateral case", "governing_lateral_case", ""), ("Extra axial load per column", "staging_extra_axial_per_column_kn", "kN"),\n        ("Load at column tops", "total_dead_load_kn", "kN"), ("Staging self weight", "staging_self_weight_kn", "kN"),\n        ("Load on foundation", "foundation_load_kn", "kN"), ("Foundation type", "foundation_type", ""), ("Foundation size", "foundation_size_m", "m")]),\n    ("Quantities (rough)", [\n        ("Concrete in total", "concrete_volume_m3", "m³"), ("of which cone", "cone_volume_m3", "m³"),\n        ("of which bracing beams", "bracing_volume_m3", "m³"), ("of which foundation", "foundation_volume_m3", "m³"),\n        ("Steel (assumed intensities)", "estimated_steel_kg", "kg")]),\n]\n\n\ndef _num(name, lo, hi, label, source):\n    raw = (source.get(name) or "").strip()\n    try:\n        v = float(raw)\n    except ValueError:\n        raise ValueError(f"{label}: enter a number.")\n    if not lo <= v <= hi:\n        raise ValueError(f"{label} must be between {lo} and {hi}.")\n    return v\n\n\n@app.route("/design/detail")\n@need("view")\ndef design_detail():\n    src = request.args\n    try:\n        vals = {k: _num(k, lo, hi, label, src) for k, (lo, hi, label) in DESIGN_LIMITS.items()}\n        n = int(_num("num_columns", 6, 16, "Columns", src))\n        grade = int(_num("grade", 20, 40, "Concrete grade", src))\n        if grade not in (20, 25, 30, 35, 40):\n            raise ValueError("Concrete grade must be 20, 25, 30, 35 or 40.")\n    except ValueError as e:\n        flash(str(e), "error")\n        return redirect(url_for("design"))\n    inputs = DesignInputs(\n        capacity_liters=vals["capacity_kl"] * 1000, staging_height_m=vals["staging_height_m"], num_columns=n,\n        soil_bearing_capacity_kpa=vals["soil_bearing_kpa"], concrete_grade_mpa=float(grade),\n        basic_wind_speed_m_s=vals["wind_speed_m_s"], seismic_zone_factor=vals["seismic_zone_factor"])\n    out = design_intze_tank(inputs)\n    cost = total_relative_cost(out.concrete_volume_m3, grade, n, out.estimated_steel_kg)\n    fig = vt.make_single_figure(inputs, out, cost)\n    sections = []\n    for title, rows in OUTPUT_ROWS:\n        items = []\n        for label, field, unit in rows:\n            if field is None:\n                val = f"{out.ring_beam_width_mm:.0f} × {out.ring_beam_depth_mm:.0f}"\n            else:\n                v = getattr(out, field)\n                val = f"{v:,.2f}".rstrip("0").rstrip(".") if isinstance(v, float) else str(v)\n            items.append((label, val, unit))\n        sections.append((title, items))\n    slender = [w for w in out.warnings if "Slenderness" in w]\n    return render_template("detail.html", page="design", inputs=inputs, out=out, cost=cost,\n                           sections=sections, fig_json=fig.to_json(), vals=vals, n=n, grade=grade,\n                           slender=slender)\n\n\n# ------------------------------------------------------------ regional planner\nDEMO_ZONES_CSV = """name,lat,lon,population,area_km2,density_per_km2,lpcd,growth_rate_pct\nDEMO Zone A,26.7200,88.4300,18000,,,135,1.5\nDEMO Zone B,26.7290,88.4380,12000,,,135,1.5\nDEMO Zone C,26.7120,88.4420,,1.80,6500,135,2.0\nDEMO Zone D,26.7350,88.4250,6000,,,100,1.0\nDEMO Zone E,26.7080,88.4250,,0.66,5500,135,1.5\nDEMO Zone F,26.7400,88.4500,9500,,,135,1.5\n"""\n\n\n@app.route("/regional", methods=["GET", "POST"])\n@need("view")\ndef regional():\n    text = DEMO_ZONES_CSV\n    result = None\n    if request.method == "POST":\n        text = (request.form.get("zones") or "").strip() + "\\n"\n        if len(text) > 20000:\n            flash("That is too much text for a zone list (limit 20,000 characters).", "error")\n            return render_template("regional.html", page="regional", text=text, result=None)\n        try:\n            zones = rp.load_zones_from_text(text)\n            if not zones:\n                raise ValueError("No zones found. The first line must be the column names.")\n            arrangements = quiet(rp.plan, zones)\n            if not arrangements:\n                flash("No arrangement satisfies the service-radius and tank-size limits. "\n                      "Increase the radius, allow bigger tanks or add zones.", "error")\n            else:\n                best = min(arrangements, key=rp.total)\n                fig = rp.build_plain_map_figure(zones, best)\n                tanks = []\n                for i, grp in enumerate(sorted(best["groups"], key=lambda g_: g_["zones"]), 1):\n                    d = grp["design"]\n                    tanks.append({"no": i, "cap": grp["capacity_kl"], "need": grp["need_kl"],\n                                  "serves": ", ".join(zones[j]["name"] for j in grp["zones"]),\n                                  "staging": grp["staging_m"], "far": max(grp["dists"]), "d": d})\n                by_k = []\n                for k in sorted({a_["k"] for a_ in arrangements}):\n                    a2 = min((x for x in arrangements if x["k"] == k), key=rp.total)\n                    by_k.append({"k": k, "total": rp.total(a2), "tank": a2["tank_cost"],\n                                 "oh": rp.SITE_OVERHEAD * k, "dist": a2["dist_cost"], "best": a2 is best})\n                sens = []\n                for oh in (0, 10, 20, 40, 80, 160, 320):\n                    b2 = min(arrangements, key=lambda a_: rp.total(a_, oh))\n                    sens.append({"oh": oh, "k": b2["k"], "total": rp.total(b2, oh)})\n                result = {"zones": zones, "tanks": tanks, "best": best, "total": rp.total(best),\n                          "by_k": by_k, "sens": sens, "fig_json": fig.to_json(),\n                          "years": rp.DESIGN_YEARS, "frac": rp.STORAGE_FRACTION,\n                          "radius": rp.MAX_SERVICE_RADIUS_KM, "overhead": rp.SITE_OVERHEAD}\n        except SystemExit as e:\n            flash(str(e), "error")\n        except Exception as e:\n            flash(f"Could not read the zone list: {e}", "error")\n    return render_template("regional.html", page="regional", text=text, result=result)\n\n\n@app.route("/advice")\n@need("view")\ndef advice():\n    if not project_exists():\n        return render_template("empty.html", page="advice")\n    st = get_state()\n    a = ct.analyse(st)\n    st["last_options"] = a["options"]\n    ct.save_state(st)\n    return render_template("advice.html", page="advice", st=st, a=a,\n                           plan=st["plan"], locked=ct.locked_columns(st))\n\n\n# ------------------------------------------------------------ actions\n@app.route("/project/start", methods=["POST"])\n@need("start")\ndef start_project():\n    if not project_exists():\n        st = quiet(ct.new_state)\n        ct.save_state(st)\n        flash("Project created with the optimiser\'s balanced pick as the starting plan.", "ok")\n    return redirect(url_for("overview"))\n\n\n@app.route("/progress", methods=["POST"])\n@need("log")\ndef post_progress():\n    st = get_state()\n    stage = request.form.get("stage", "")\n    try:\n        pct = float(request.form.get("percent", ""))\n    except ValueError:\n        flash("Enter the completed percentage as a number from 0 to 100.", "error")\n        return redirect(url_for("site_desk"))\n    if stage not in ct.STAGE_WEIGHTS:\n        abort(400)\n    quiet(ct.set_progress, st, stage, pct)\n    st["log"][-1]["text"] = by(st["log"][-1]["text"])\n    ct.save_state(st)\n    flash(f"{STAGE_LABEL[stage]} is now {max(0, min(100, pct)):.0f}% complete.", "ok")\n    return redirect(url_for("site_desk"))\n\n\n@app.route("/stock", methods=["POST"])\n@need("log")\ndef post_stock():\n    st = get_state()\n    grade = request.form.get("grade", "")\n    raw = request.form.get("m3", "").strip().lower()\n    if grade not in {str(x) for x in ct.GRADES}:\n        abort(400)\n    if raw in ("", "none", "unlimited"):\n        quiet(ct.set_stock, st, grade, None)\n        msg = f"M{grade} stock set to unlimited."\n    else:\n        try:\n            val = float(raw)\n            if val < 0:\n                raise ValueError\n        except ValueError:\n            flash("Enter the available concrete in cubic metres, or leave it empty for unlimited.", "error")\n            return redirect(url_for("site_desk"))\n        quiet(ct.set_stock, st, grade, val)\n        msg = f"M{grade} stock set to {val:.1f} m3."\n    st["log"][-1]["text"] = by(st["log"][-1]["text"])\n    ct.save_state(st)\n    flash(msg, "ok")\n    return redirect(url_for("site_desk"))\n\n\n@app.route("/site-data", methods=["POST"])\n@need("site_data")\ndef post_site_data():\n    st = get_state()\n    changed = []\n    refused = []\n    for key in ct.DEFAULT_SITE:\n        raw = request.form.get(key, "").strip()\n        if not raw:\n            continue\n        try:\n            value = float(raw)\n        except ValueError:\n            flash(f"\'{raw}\' is not a valid number for {key.replace(\'_\', \' \')}.", "error")\n            return redirect(url_for("site_desk"))\n        if value == float(st["site"][key]):\n            continue\n        quiet(ct.set_site, st, key, raw)\n        last = st["log"][-1] if st["log"] else None\n        if last and last["type"] == "refused":\n            refused.append(last["text"])\n            continue\n        st["log"][-1]["text"] = by(st["log"][-1]["text"])\n        changed.append(key)\n    cap = request.form.get("max_cost", "").strip().lower()\n    try:\n        new_cap = None if cap in ("", "none") else float(cap)\n    except ValueError:\n        flash("Enter the cost cap as a number, or leave it empty for none.", "error")\n        return redirect(url_for("site_desk"))\n    if new_cap != st["max_cost"]:\n        st["max_cost"] = new_cap\n        ct.log(st, "cap", by(f"Cost cap set to {new_cap}."))\n        changed.append("cost cap")\n    ct.save_state(st)\n    for text in refused:\n        flash(text, "error")\n    if changed:\n        flash("Saved. Changed: " + ", ".join(c.replace("_", " ") for c in changed)\n              + ". Open Advice to see what it means for the plan.", "ok")\n    elif not refused:\n        flash("Nothing changed.", "ok")\n    return redirect(url_for("site_desk"))\n\n\n@app.route("/accept", methods=["POST"])\n@need("approve")\ndef post_accept():\n    st = get_state()\n    quiet(ct.accept, st, request.form.get("option", "0"))\n    if st["log"] and st["log"][-1]["type"] == "decision":\n        st["log"][-1]["text"] = by(st["log"][-1]["text"])\n    ct.save_state(st)\n    flash("Plan updated for all work not yet started.", "ok")\n    return redirect(url_for("advice"))\n\n\n# ------------------------------------------------------------ errors\n@app.errorhandler(403)\ndef forbidden(e):\n    return render_template("denied.html", page=""), 403\n\n\n@app.errorhandler(400)\ndef bad(e):\n    return render_template("denied.html", page="", bad=True), 400\n\n\nif __name__ == "__main__":\n    print("Intze Tank Platform running at  http://127.0.0.1:5000   (Ctrl+C to stop)")\n    app.run(host="127.0.0.1", port=5000, debug=False)\n',
    'templates/base.html': '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>{% block title %}Intze Tank Platform{% endblock %}</title>\n<link rel="stylesheet" href="{{ url_for(\'static\', filename=\'style.css\') }}">\n</head>\n<body class="{% block bodyclass %}{% endblock %}">\n{% block body %}\n<header class="bar">\n  <a class="brand" href="{{ url_for(\'overview\') }}">Intze<span>engine</span></a>\n  {% if user %}\n  <nav class="nav" aria-label="Main">\n    <a href="{{ url_for(\'overview\') }}" {% if page == \'overview\' %}aria-current="page"{% endif %}>Overview</a>\n    {% if \'log\' in can %}<a href="{{ url_for(\'site_desk\') }}" {% if page == \'site\' %}aria-current="page"{% endif %}>Site desk</a>{% endif %}\n    <a href="{{ url_for(\'design\') }}" {% if page == \'design\' %}aria-current="page"{% endif %}>Design</a>\n    <a href="{{ url_for(\'regional\') }}" {% if page == \'regional\' %}aria-current="page"{% endif %}>Regional</a>\n    <a href="{{ url_for(\'advice\') }}" {% if page == \'advice\' %}aria-current="page"{% endif %}>Advice</a>\n  </nav>\n  <div class="who">\n    <span><b>{{ role_label[user.role] }}</b></span>\n    <form method="post" action="{{ url_for(\'logout\') }}">\n      <input type="hidden" name="csrf" value="{{ csrf_token() }}">\n      <button class="btn quiet" type="submit">Sign out</button>\n    </form>\n  </div>\n  {% endif %}\n</header>\n<main class="wrap">\n  {% with msgs = get_flashed_messages(with_categories=true) %}\n    {% for cat, m in msgs %}<div class="flash {{ cat }}" role="status">{{ m }}</div>{% endfor %}\n  {% endwith %}\n  {% block content %}{% endblock %}\n</main>\n{% endblock %}\n</body>\n</html>\n',
    'templates/design.html': '{% extends "base.html" %}\n{% block title %}Design · Intze Tank Platform{% endblock %}\n{% block content %}\n<section>\n  <h2>Design</h2>\n  <p class="sub">Enter the site and the optimiser returns the best trade-offs between cost and load on each staging column. Every design shown has been re-computed on the real design engine. Costs are relative and illustrative, and wind and seismic use simplified static methods.</p>\n  <form class="card" method="post" action="{{ url_for(\'design\') }}">\n    <input type="hidden" name="csrf" value="{{ csrf_token() }}">\n    <div class="row">\n      <div class="field"><label for="capacity_kl">{{ limits.capacity_kl[2] }}</label>\n        <input id="capacity_kl" name="capacity_kl" type="number" step="10" value="{{ form.capacity_kl }}" required></div>\n      <div class="field"><label for="staging_height_m">{{ limits.staging_height_m[2] }}</label>\n        <input id="staging_height_m" name="staging_height_m" type="number" step="0.5" value="{{ form.staging_height_m }}" required></div>\n    </div>\n    <div class="row">\n      <div class="field"><label for="wind_speed_m_s">{{ limits.wind_speed_m_s[2] }}</label>\n        <input id="wind_speed_m_s" name="wind_speed_m_s" type="number" step="1" value="{{ form.wind_speed_m_s }}" required></div>\n      <div class="field"><label for="seismic_zone_factor">{{ limits.seismic_zone_factor[2] }}</label>\n        <input id="seismic_zone_factor" name="seismic_zone_factor" type="number" step="0.01" value="{{ form.seismic_zone_factor }}" required></div>\n    </div>\n    <div class="field"><label for="soil_bearing_kpa">{{ limits.soil_bearing_kpa[2] }}</label>\n      <input id="soil_bearing_kpa" name="soil_bearing_kpa" type="number" step="5" value="{{ form.soil_bearing_kpa }}" required></div>\n    <button class="btn primary" type="submit">Find designs</button>\n  </form>\n</section>\n\n<section>\n  <h2>Check one design</h2>\n  <p class="sub">Already have a number of columns and a grade in mind? Choose them here to see the full design with the same site values as above, a 3D view and a printable summary.</p>\n  <form class="card" method="get" action="{{ url_for(\'design_detail\') }}">\n    <input type="hidden" name="capacity_kl" value="{{ form.capacity_kl }}">\n    <input type="hidden" name="staging_height_m" value="{{ form.staging_height_m }}">\n    <input type="hidden" name="soil_bearing_kpa" value="{{ form.soil_bearing_kpa }}">\n    <input type="hidden" name="wind_speed_m_s" value="{{ form.wind_speed_m_s }}">\n    <input type="hidden" name="seismic_zone_factor" value="{{ form.seismic_zone_factor }}">\n    <div class="row">\n      <div class="field"><label for="num_columns">Columns</label>\n        <select id="num_columns" name="num_columns">{% for n in (6, 8, 10, 12) %}<option value="{{ n }}" {% if n == 10 %}selected{% endif %}>{{ n }}</option>{% endfor %}</select></div>\n      <div class="field"><label for="grade">Concrete grade</label>\n        <select id="grade" name="grade">{% for g in (20, 25, 30, 35, 40) %}<option value="{{ g }}" {% if g == 25 %}selected{% endif %}>M{{ g }}</option>{% endfor %}</select></div>\n    </div>\n    <button class="btn" type="submit">Show this design</button>\n  </form>\n</section>\n\n{% if results %}\n<section>\n  <h2>Options</h2>\n  <p class="sub">Cheapest first. More columns lower the load on each column but cost more; a higher grade lowers it a little more. There is no single best answer, so the engineer chooses.{% if dropped %} {{ dropped }} candidate{{ \'s\' if dropped > 1 }} removed because the real engine showed {{ \'it was\' if dropped == 1 else \'they were\' }} beaten by another.{% endif %}</p>\n  {% for r in results %}\n  <div class="card opt">\n    <div>\n      <h3>{{ r.num_columns }} columns, M{{ r.concrete_grade_mpa }}</h3>\n      <p>Relative cost {{ \'%.1f\'|format(r.real_cost) }} · extra axial load {{ \'%.0f\'|format(r.real_extra_axial_kn) }} kN per column · column diameter {{ \'%.0f\'|format(r.real_column_dia_mm) }} mm</p>\n    </div>\n    <a class="btn" href="{{ url_for(\'design_detail\', capacity_kl=form.capacity_kl, staging_height_m=form.staging_height_m, soil_bearing_kpa=form.soil_bearing_kpa, wind_speed_m_s=form.wind_speed_m_s, seismic_zone_factor=form.seismic_zone_factor, num_columns=r.num_columns, grade=r.concrete_grade_mpa|int) }}">Details and 3D</a>\n  </div>\n  {% endfor %}\n</section>\n{% endif %}\n{% endblock %}\n',
    'templates/detail.html': '{% extends "base.html" %}\n{% block title %}Design details · Intze Tank Platform{% endblock %}\n{% block content %}\n<section class="printable">\n  <div class="noprint"><a class="note" href="javascript:history.back()">← back to the options</a></div>\n  <h2>{{ n }} columns, M{{ grade }}</h2>\n  <p class="sub">Capacity {{ \'%.0f\'|format(vals.capacity_kl) }} kL · staging {{ \'%.1f\'|format(vals.staging_height_m) }} m · wind {{ \'%.0f\'|format(vals.wind_speed_m_s) }} m/s · seismic factor {{ vals.seismic_zone_factor }} · soil {{ \'%.0f\'|format(vals.soil_bearing_kpa) }} kPa · relative cost {{ \'%.1f\'|format(cost) }}</p>\n\n  {% if slender %}<div class="alert"><b>Not valid as shown.</b> {{ slender[0] }}</div>{% endif %}\n  {% for w in out.warnings if \'Slenderness\' not in w %}<div class="alert"><b>Note.</b> {{ w }}</div>{% endfor %}\n\n  <div class="card noprint" style="padding:8px">\n    <div id="tank3d" role="img" aria-label="3D model of the tank"></div>\n  </div>\n  <p class="note noprint">Drag to rotate, scroll to zoom. A schematic: column positions and bracing are illustrative.</p>\n\n  <div class="grid g2" style="margin-top:28px">\n    {% for title, items in sections %}\n    <div class="card">\n      <h3 style="margin-bottom:14px">{{ title }}</h3>\n      <table class="kv">\n        {% for label, val, unit in items %}<tr><td>{{ label }}</td><td>{{ val }} {{ unit }}</td></tr>{% endfor %}\n      </table>\n    </div>\n    {% endfor %}\n  </div>\n\n  <div class="card" style="margin-top:16px">\n    <h3 style="margin-bottom:14px">Assumptions used for this design</h3>\n    <ul class="assump">{% for a in out.assumptions %}<li>{{ a }}</li>{% endfor %}</ul>\n  </div>\n  <p class="note" style="margin-top:18px">Decision-support only. Costs are relative (illustrative), wind and seismic use simplified static methods, and several members (ring beam, cone, raft, bracing) use placeholder rules. A licensed structural engineer must check and sign off any design before use.</p>\n  <p class="noprint" style="margin-top:24px"><button class="btn primary" type="button" onclick="window.print()">Print or save as PDF</button></p>\n</section>\n<script src="{{ url_for(\'vendor_plotly\') }}"></script>\n<script>\n  var fig = {{ fig_json|safe }};\n  Plotly.newPlot(\'tank3d\', fig.data, fig.layout, {responsive: true, displaylogo: false});\n</script>\n{% endblock %}\n',
    'templates/regional.html': '{% extends "base.html" %}\n{% block title %}Regional · Intze Tank Platform{% endblock %}\n{% block content %}\n<section>\n  <h2>Regional planner</h2>\n  <p class="sub">Give the villages or zones of an area. The planner forecasts demand, sizes storage at one third of daily demand, tries every way of grouping the zones into tanks, designs each tank with the real engine, and shows the cheapest arrangement. The zones below are demonstration data, not a real district.</p>\n  <form class="card" method="post" action="{{ url_for(\'regional\') }}">\n    <input type="hidden" name="csrf" value="{{ csrf_token() }}">\n    <div class="field"><label for="zones">Zones (CSV, at most 8). Columns: name, lat, lon, population (or area_km2 + density_per_km2), lpcd, growth_rate_pct, optional soil_bearing_kpa, wind_speed_m_s, seismic_zone_factor, polygon</label>\n      <textarea id="zones" name="zones" rows="9" spellcheck="false">{{ text }}</textarea></div>\n    <button class="btn primary" type="submit">Plan the tanks</button>\n  </form>\n</section>\n\n{% if result %}\n<section>\n  <h2>Cheapest arrangement: {{ result.best.k }} tank{{ \'s\' if result.best.k > 1 }}</h2>\n  <p class="sub">Total relative cost {{ \'%.0f\'|format(result.total) }} (tank structures {{ \'%.0f\'|format(result.best.tank_cost) }} + site overhead {{ \'%.0f\'|format(result.overhead * result.best.k) }} + distribution proxy {{ \'%.0f\'|format(result.best.dist_cost) }}). Design year +{{ result.years }} years, storage {{ \'%.2f\'|format(result.frac) }} × daily demand, service radius {{ result.radius }} km.</p>\n  <div class="card" style="padding:8px"><div id="map" role="img" aria-label="Map of zones and tanks"></div></div>\n  {% for t in result.tanks %}\n  <div class="card opt" style="margin-top:14px">\n    <div>\n      <h3>Tank {{ t.no }}: {{ t.cap }} kL <em>serves {{ t.serves }}</em></h3>\n      <p>Needs {{ \'%.0f\'|format(t.need) }} kL · staging {{ t.staging }} m · farthest zone {{ \'%.2f\'|format(t.far) }} km</p>\n      <p>{{ t.d.n }} columns, M{{ t.d.grade }}, column dia {{ \'%.0f\'|format(t.d.col_dia) }} mm, tank dia {{ \'%.1f\'|format(t.d.diameter) }} m, {{ t.d.foundation|replace(\'_\', \' \') }}, extra load {{ \'%.0f\'|format(t.d.axial) }} kN per column ({{ t.d.case }} governs), concrete {{ \'%.0f\'|format(t.d.volume) }} m³{% if t.d.slender_warn %} · <b>slenderness limit exceeded: add bracing tiers</b>{% endif %}</p>\n    </div>\n  </div>\n  {% endfor %}\n</section>\n\n<section class="grid g2">\n  <div class="card">\n    <h3 style="margin-bottom:14px">Zones and demand</h3>\n    <table class="kv">\n      <tr><td><b>zone</b></td><td><b>design pop.</b></td><td><b>kL/day</b></td><td><b>storage kL</b></td></tr>\n      {% for z in result.zones %}<tr><td>{{ z.name }}</td><td>{{ \'{:,.0f}\'.format(z.design_pop) }}</td><td>{{ \'{:,.0f}\'.format(z.demand_kl_day) }}</td><td>{{ \'{:,.0f}\'.format(z.storage_kl) }}</td></tr>{% endfor %}\n    </table>\n  </div>\n  <div class="card">\n    <h3 style="margin-bottom:14px">Best for each number of tanks</h3>\n    <table class="kv">\n      <tr><td><b>tanks</b></td><td><b>total</b></td><td><b>structures</b></td><td><b>overhead</b></td></tr>\n      {% for r in result.by_k %}<tr><td>{{ r.k }}{% if r.best %} ← cheapest{% endif %}</td><td>{{ \'%.0f\'|format(r.total) }}</td><td>{{ \'%.0f\'|format(r.tank) }}</td><td>{{ \'%.0f\'|format(r.oh) }}</td></tr>{% endfor %}\n    </table>\n    <h3 style="margin:22px 0 10px">How much the answer depends on site overhead</h3>\n    <p class="note">Overhead is an illustrative number. If the cheapest tank count changes as it changes, the answer is not robust.</p>\n    <table class="kv">\n      {% for s in result.sens %}<tr><td>overhead {{ s.oh }}</td><td>{{ s.k }} tank{{ \'s\' if s.k > 1 }}, total {{ \'%.0f\'|format(s.total) }}</td></tr>{% endfor %}\n    </table>\n  </div>\n</section>\n<script src="{{ url_for(\'vendor_plotly\') }}"></script>\n<script>\n  var fig = {{ result.fig_json|safe }};\n  Plotly.newPlot(\'map\', fig.data, fig.layout, {responsive: true, displaylogo: false});\n</script>\n{% endif %}\n{% endblock %}\n',
    'static/style.css': '/* Intze Tank Platform -- dark, thin-type look based on the student\'s reference.\n   One accent (rose) is used for state and primary actions only. */\n:root {\n  --ink: #0c0c0e;\n  --panel: #141417;\n  --raised: #1b1b20;\n  --line: #2c2c33;\n  --line-soft: #202026;\n  --text: #edebe7;\n  --muted: #9a9aa4;\n  --accent: #e8556d;\n  --accent-soft: rgba(232, 85, 109, .14);\n  --good: #8fd6b4;\n  --warn: #f0b765;\n  --radius: 22px;\n  --display: "Outfit", "Segoe UI", system-ui, sans-serif;\n  --serif: "Instrument Serif", "Georgia", serif;\n}\n\n* { box-sizing: border-box; }\nhtml { color-scheme: dark; }\nbody {\n  margin: 0;\n  background: var(--ink);\n  color: var(--text);\n  font-family: var(--display);\n  font-weight: 300;\n  font-size: 17px;\n  line-height: 1.6;\n  -webkit-font-smoothing: antialiased;\n}\na { color: inherit; }\nbutton, input, select { font: inherit; color: inherit; }\n:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 6px; }\n\n/* ---------- top bar ---------- */\n.bar {\n  display: flex; align-items: center; justify-content: space-between; gap: 24px;\n  padding: 22px clamp(20px, 4vw, 56px);\n  border-bottom: 1px solid var(--line-soft);\n}\n.brand { font-weight: 400; letter-spacing: .02em; text-decoration: none; font-size: 18px; }\n.brand span { font-family: var(--serif); font-style: italic; font-size: 22px; color: var(--muted); margin-left: 6px; }\n.nav { display: flex; gap: clamp(14px, 3vw, 40px); }\n.nav a {\n  text-decoration: none; font-size: 13px; letter-spacing: .14em; text-transform: uppercase;\n  color: var(--muted); padding: 6px 2px; border-bottom: 1px solid transparent;\n}\n.nav a:hover { color: var(--text); }\n.nav a[aria-current="page"] { color: var(--text); border-bottom-color: var(--accent); }\n.who { display: flex; align-items: center; gap: 14px; font-size: 14px; color: var(--muted); }\n.who b { font-weight: 400; color: var(--text); }\n.who form { margin: 0; }\n\n/* ---------- layout ---------- */\n.wrap { max-width: 1240px; margin: 0 auto; padding: clamp(28px, 5vw, 72px) clamp(20px, 4vw, 56px) 96px; }\nh1, h2, h3 { font-weight: 200; margin: 0; letter-spacing: .01em; line-height: 1.05; }\nh2 { font-size: clamp(30px, 4vw, 46px); margin-bottom: 8px; }\nh3 { font-size: 22px; font-weight: 300; line-height: 1.25; }\n.sub { color: var(--muted); max-width: 62ch; margin: 0 0 32px; }\nsection + section { margin-top: clamp(48px, 7vw, 96px); }\n\n.card {\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  background: linear-gradient(180deg, #17171b 0%, #101013 100%);\n  padding: 28px;\n}\n.grid { display: grid; gap: 16px; }\n.g3 { grid-template-columns: repeat(3, 1fr); }\n.g2 { grid-template-columns: repeat(2, 1fr); }\n@media (max-width: 880px) { .g3, .g2 { grid-template-columns: 1fr; } .nav { display: none; } }\n\n/* ---------- hero (overview) ---------- */\n.hero { display: grid; grid-template-columns: 1.3fr 1fr; gap: 32px; align-items: center; }\n@media (max-width: 880px) { .hero { grid-template-columns: 1fr; } }\n.big {\n  font-size: clamp(88px, 15vw, 210px); font-weight: 100; line-height: .9; letter-spacing: -.02em;\n}\n.big small { font-size: .32em; font-weight: 200; letter-spacing: 0; }\n.accent-serif { font-family: var(--serif); font-style: italic; font-weight: 400; color: var(--muted); font-size: clamp(30px, 4vw, 52px); margin-left: 10px; }\n.ring { width: min(100%, 300px); justify-self: end; }\n.ring circle { fill: none; stroke-width: 3; }\n.ring .track { stroke: var(--line); }\n.ring .fill { stroke: var(--accent); stroke-linecap: round; transform: rotate(-90deg); transform-origin: 50% 50%;\n  animation: draw 1.4s cubic-bezier(.2,.7,.2,1) both; }\n@keyframes draw { from { stroke-dashoffset: var(--len); } }\n@media (prefers-reduced-motion: reduce) { .ring .fill { animation: none; } }\n.ring text { fill: var(--muted); font-family: var(--display); font-size: 9px; font-weight: 300; }\n\n/* ---------- stage cards ---------- */\n.stage { display: flex; flex-direction: column; gap: 14px; min-height: 150px; }\n.stage .top { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; }\n.stage .pct { font-size: 38px; font-weight: 200; }\n.meter { height: 2px; background: var(--line); border-radius: 2px; overflow: hidden; margin-top: auto; }\n.meter i { display: block; height: 100%; background: var(--accent); }\n.tag { font-size: 13px; color: var(--muted); border: 1px solid var(--line); border-radius: 99px; padding: 2px 10px; white-space: nowrap; }\n.tag.locked { color: var(--warn); border-color: rgba(240,183,101,.4); }\n\n/* ---------- facts ---------- */\n.facts { display: grid; grid-template-columns: repeat(2, 1fr); gap: 22px 28px; margin: 18px 0 0; }\n.facts dt { color: var(--muted); font-size: 14px; }\n.facts dd { margin: 0; font-size: 26px; font-weight: 200; }\n\n/* ---------- log ---------- */\n.log { list-style: none; margin: 0; padding: 0; }\n.log li { display: grid; grid-template-columns: 150px 1fr; gap: 16px; padding: 14px 0; border-bottom: 1px solid var(--line-soft); }\n.log li:last-child { border-bottom: 0; }\n.log time { color: var(--muted); font-size: 14px; }\n@media (max-width: 640px) { .log li { grid-template-columns: 1fr; gap: 2px; } }\n\n/* ---------- forms ---------- */\nlabel { display: block; font-size: 14px; color: var(--muted); margin-bottom: 6px; }\ninput[type=text], input[type=password], input[type=number], select {\n  width: 100%; background: transparent; border: 1px solid var(--line); border-radius: 14px;\n  padding: 12px 16px; font-weight: 300;\n}\nselect option { background: var(--panel); }\ninput:disabled, select:disabled { opacity: .45; cursor: not-allowed; }\n.field { margin-bottom: 16px; }\n.row { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }\n.btn {\n  display: inline-flex; align-items: center; gap: 10px; cursor: pointer;\n  border: 1px solid var(--text); background: transparent; border-radius: 99px; padding: 11px 26px;\n  font-weight: 400; letter-spacing: .02em;\n}\n.btn:hover { background: var(--text); color: var(--ink); }\n.btn.primary { border-color: var(--accent); background: var(--accent); color: #1a0509; }\n.btn.primary:hover { background: #f2748a; border-color: #f2748a; color: #1a0509; }\n.btn.quiet { border-color: var(--line); color: var(--muted); padding: 7px 18px; font-size: 14px; }\n.btn.quiet:hover { color: var(--ink); }\n.btn:disabled { opacity: .4; cursor: not-allowed; }\n.note { color: var(--muted); font-size: 14px; }\n.lockbox { border: 1px dashed var(--line); border-radius: var(--radius); padding: 22px 28px; color: var(--muted); }\n.lockbox b { color: var(--text); font-weight: 400; }\n\n.flash { border-radius: 14px; padding: 12px 18px; margin-bottom: 28px; border: 1px solid var(--line); }\n.flash.ok { border-color: rgba(143,214,180,.45); color: var(--good); }\n.flash.error { border-color: rgba(232,85,109,.55); color: #ff9aab; }\n\n/* ---------- advice ---------- */\n.alert { border-left: 2px solid var(--accent); padding: 4px 0 4px 20px; margin-bottom: 18px; }\n.alert b { font-weight: 400; }\n.opt { display: grid; grid-template-columns: 1fr auto; gap: 18px; align-items: center; }\n.opt + .opt { margin-top: 14px; }\n.opt h3 em { font-family: var(--serif); font-style: italic; color: var(--muted); font-weight: 400; }\n.opt p { margin: 6px 0 0; color: var(--muted); font-size: 15px; }\n@media (max-width: 640px) { .opt { grid-template-columns: 1fr; } }\n\n/* ---------- login ---------- */\nbody.login {\n  min-height: 100vh;\n  background:\n    radial-gradient(ellipse 70% 55% at 50% 0%, #26262d 0%, rgba(12,12,14,0) 70%),\n    var(--ink);\n}\n.login main { max-width: 1100px; margin: 0 auto; padding: clamp(40px, 9vh, 110px) 24px 80px; text-align: center; }\n.login h1 { font-size: clamp(40px, 8vw, 104px); font-weight: 200; letter-spacing: .06em; text-transform: uppercase; line-height: 1.02; }\n.login h1 .serif { display: block; text-transform: none; letter-spacing: 0; font-family: var(--serif); font-style: italic; font-weight: 400; color: var(--muted); font-size: 1.05em; }\n.login .lede { color: var(--muted); max-width: 52ch; margin: 28px auto 48px; }\n.panel { max-width: 420px; margin: 0 auto; text-align: left; }\n.roles { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin-top: 28px; }\n.demo { max-width: 420px; margin: 22px auto 0; font-size: 14px; color: var(--muted); text-align: left; }\n.demo table { width: 100%; border-collapse: collapse; margin-top: 8px; }\n.demo td { padding: 6px 0; border-bottom: 1px solid var(--line-soft); }\n.demo td:last-child { text-align: right; font-variant-numeric: tabular-nums; }\n\n.center-page { text-align: center; padding-top: 12vh; }\n.center-page h1 { font-size: clamp(40px, 7vw, 84px); }\n\n/* ---------- tables, text areas, print ---------- */\ntextarea { width: 100%; background: transparent; border: 1px solid var(--line); border-radius: 14px; padding: 12px 16px;\n  font-family: ui-monospace, Consolas, monospace; font-size: 14px; color: inherit; }\n.kv { width: 100%; border-collapse: collapse; }\n.kv td { padding: 8px 0; border-bottom: 1px solid var(--line-soft); vertical-align: top; }\n.kv td:last-child { text-align: right; font-variant-numeric: tabular-nums; }\n.assump { margin: 0; padding-left: 20px; color: var(--muted); font-size: 15px; }\n.assump li { margin-bottom: 8px; }\n.opt .btn { white-space: nowrap; }\n@media print {\n  html { color-scheme: light; }\n  body { background: #fff; color: #111; font-size: 12pt; }\n  .bar, .noprint, .flash { display: none !important; }\n  .card { background: #fff; border: 1px solid #bbb; break-inside: avoid; padding: 14px; }\n  .sub, .note, .assump, .kv td { color: #222; }\n  h2, h3 { color: #000; }\n  .wrap { padding: 0; max-width: none; }\n}\n',
    'visualize_tank.py': '"""\n3D parametric visualization of the Intze tank.\n\nRuns the optimizer for a site, takes every Pareto-optimal design it\nfinds, re-computes each with the real engine, and draws them as an\ninteractive 3D model in one HTML file (tank_3d.html). A dropdown in\nthe file switches between the candidate designs; rotate with the\nmouse, zoom with the scroll wheel.\n\nEverything drawn comes straight from the engine\'s outputs (diameter,\nwall height, dome rises, cone geometry, staging height, number of\ncolumns, column diameter, bracing tiers, water level) -- nothing is\nhand-drawn. Elements the engine does not size are marked "schematic"\nin the figure.\n"""\n\nimport math\nimport numpy as np\nimport plotly.graph_objects as go\n\nfrom models import DesignInputs\nfrom intze_design_engine import design_intze_tank\nfrom cost_model import total_relative_cost\n\nCOL_CONCRETE = "#9aa0a6"\nCOL_WATER = "#3b82f6"\nCOL_RING = "#5f6368"\nCOL_GROUND = "#c8b89a"\n\nN_THETA = 60\n\n\ndef _surface(X, Y, Z, color, opacity=1.0, name="", hover=None):\n    return go.Surface(\n        x=X, y=Y, z=Z, showscale=False, opacity=opacity, name=name,\n        colorscale=[[0, color], [1, color]], hoverinfo="text" if hover else "skip",\n        text=hover, lighting=dict(ambient=0.6, diffuse=0.7, specular=0.1),\n    )\n\n\ndef _revolve(radii, zs, color, opacity=1.0, name="", hover=None):\n    theta = np.linspace(0, 2 * math.pi, N_THETA)\n    r = np.array(radii)[:, None]\n    X = r * np.cos(theta)[None, :]\n    Y = r * np.sin(theta)[None, :]\n    Z = np.array(zs)[:, None] * np.ones_like(theta)[None, :]\n    return _surface(X, Y, Z, color, opacity, name, hover)\n\n\ndef _dome(base_radius, rise, z_base, upward, color, name, hover):\n    Rs = (base_radius ** 2 + rise ** 2) / (2 * rise)\n    phi_max = math.asin(min(1.0, base_radius / Rs))\n    phis = np.linspace(0, phi_max, 20)\n    radii = Rs * np.sin(phis)\n    height = Rs * np.cos(phis) - (Rs - rise)\n    zs = z_base + height if upward else z_base - height\n    return _revolve(radii, zs, color, 1.0, name, hover)\n\n\ndef build_design_traces(inputs, out):\n    traces = []\n    D = out.internal_diameter_m\n    R = D / 2\n    h_s = inputs.staging_height_m\n    n = inputs.num_columns\n    col_r = out.staging_column_diameter_mm / 2000\n    r_b = out.cone_bottom_diameter_m / 2\n\n    cone_v = (R - r_b) * math.tan(math.radians(inputs.cone_angle_deg))\n    z_cone_bot = h_s\n    z0 = z_cone_bot + cone_v                    # cylinder bottom\n    cyl_h = out.cylindrical_wall_height_m       # includes free board\n    water_h = cyl_h - inputs.free_board_m\n    z_top = z0 + cyl_h\n\n    # --- staging columns ---\n    theta = np.linspace(0, 2 * math.pi, 24)\n    for k in range(n):\n        a = 2 * math.pi * k / n\n        cx, cy = R * math.cos(a), R * math.sin(a)\n        X = np.array([[cx + col_r * math.cos(t) for t in theta]] * 2)\n        Y = np.array([[cy + col_r * math.sin(t) for t in theta]] * 2)\n        Z = np.array([[0.0] * len(theta), [h_s] * len(theta)])\n        traces.append(_surface(X, Y, Z, COL_CONCRETE, 1.0, "column",\n                               f"Staging column {k+1}<br>dia {out.staging_column_diameter_mm:.0f} mm"))\n\n    # --- bracing rings at each tier (between columns) ---\n    tiers = out.staging_num_bracing_tiers\n    for t in range(1, tiers + 1):\n        z = h_s * t / tiers\n        xs = [R * math.cos(2 * math.pi * k / n) for k in range(n + 1)]\n        ys = [R * math.sin(2 * math.pi * k / n) for k in range(n + 1)]\n        traces.append(go.Scatter3d(x=xs, y=ys, z=[z] * (n + 1), mode="lines",\n                                   line=dict(color=COL_RING, width=6),\n                                   hoverinfo="text", text=f"Bracing ring, tier {t}",\n                                   name="bracing"))\n\n    # --- schematic radial beams: column tops -> cone bottom ring ---\n    for k in range(n):\n        a = 2 * math.pi * k / n\n        traces.append(go.Scatter3d(\n            x=[R * math.cos(a), r_b * math.cos(a)],\n            y=[R * math.sin(a), r_b * math.sin(a)],\n            z=[h_s, h_s], mode="lines", line=dict(color="#b0b4b9", width=4, dash="dot"),\n            hoverinfo="text", text="Support beam (schematic)", name="support beam"))\n\n    # --- foundation ---\n    if out.foundation_type == "isolated_footings":\n        side = out.foundation_size_m\n        for k in range(n):\n            a = 2 * math.pi * k / n\n            cx, cy = R * math.cos(a), R * math.sin(a)\n            X = np.array([[cx - side/2, cx + side/2, cx + side/2, cx - side/2, cx - side/2]] * 2)\n            Y = np.array([[cy - side/2, cy - side/2, cy + side/2, cy + side/2, cy - side/2]] * 2)\n            Z = np.array([[-0.5] * 5, [0.0] * 5])\n            traces.append(_surface(X, Y, Z, COL_GROUND, 1.0, "footing",\n                                   f"Isolated footing, side {side:.2f} m"))\n    else:\n        raft_r = max(out.foundation_size_m / 2, R + col_r + 0.8)\n        traces.append(_revolve([0, raft_r], [0, 0], COL_GROUND, 1.0, "raft",\n                               f"Raft foundation (schematic extent). Required equivalent "\n                               f"diameter from bearing check: {out.foundation_size_m:.2f} m"))\n        traces.append(_revolve([raft_r, raft_r], [-0.5, 0], COL_GROUND, 1.0, "raft edge", None))\n\n    # --- bottom dome (bulges downward) ---\n    traces.append(_dome(r_b, out.bottom_dome_rise_m, z_cone_bot, False, COL_CONCRETE,\n                        "bottom dome", f"Bottom dome, thickness {out.bottom_dome_thickness_mm:.0f} mm"))\n    # --- conical wall ---\n    traces.append(_revolve([r_b, R], [z_cone_bot, z0], COL_CONCRETE, 1.0, "cone",\n                           f"Conical wall, slant {out.cone_slant_height_m:.2f} m"))\n    # --- cylindrical wall ---\n    traces.append(_revolve([R, R], [z0, z_top], COL_CONCRETE, 0.55, "wall",\n                           f"Cylindrical wall<br>thickness {out.cylindrical_wall_thickness_mm:.0f} mm"\n                           f"<br>hoop steel {out.cylindrical_wall_hoop_steel_mm2_per_m:.0f} mm2/m"))\n    # --- ring beam at cone/cylinder junction ---\n    depth = out.ring_beam_depth_mm / 1000\n    traces.append(_revolve([R + 0.12, R + 0.12], [z0 - depth, z0], COL_RING, 1.0, "ring beam",\n                           f"Ring beam {out.ring_beam_width_mm:.0f} x {out.ring_beam_depth_mm:.0f} mm"))\n    # --- top dome ---\n    traces.append(_dome(R, out.top_dome_rise_m, z_top, True, COL_CONCRETE,\n                        "top dome", f"Top dome, thickness {out.top_dome_thickness_mm:.0f} mm"))\n    # --- water ---\n    traces.append(_revolve([r_b, R, R], [z_cone_bot, z0, z0 + water_h], COL_WATER, 0.35,\n                           "water", "Water"))\n    traces.append(_revolve([0, R], [z0 + water_h, z0 + water_h], COL_WATER, 0.45, "water surface", "Water level"))\n    return traces\n\n\nFOOTNOTE = dict(\n    text="Schematic: column pitch circle follows the engine\'s assumption (= tank diameter); "\n         "dotted support beams and foundation extent are illustrative.",\n    x=0.5, y=0.0, xref="paper", yref="paper", showarrow=False,\n    font=dict(size=11, color="#555"), yanchor="bottom")\n\n\ndef make_figure(site, candidates):\n    all_traces = []\n    counts = []\n    labels = []\n    notes = []\n    for c in candidates:\n        inputs = DesignInputs(\n            capacity_liters=site["capacity_liters"], staging_height_m=site["staging_height_m"],\n            num_columns=c["num_columns"], soil_bearing_capacity_kpa=site["soil_bearing_kpa"],\n            concrete_grade_mpa=float(c["concrete_grade_mpa"]),\n            basic_wind_speed_m_s=site["wind_speed_m_s"], seismic_zone_factor=site["seismic_zone_factor"],\n        )\n        out = design_intze_tank(inputs)\n        cost = total_relative_cost(out.concrete_volume_m3, c["concrete_grade_mpa"], c["num_columns"], out.estimated_steel_kg)\n        tr = build_design_traces(inputs, out)\n        all_traces.append(tr)\n        counts.append(len(tr))\n        labels.append(f"{c[\'num_columns\']} columns, M{c[\'concrete_grade_mpa\']}  |  cost {cost:.0f}  |  "\n                      f"lateral load/column {out.staging_extra_axial_per_column_kn:.0f} kN")\n        notes.append(\n            f"<b>{c[\'num_columns\']} columns, M{c[\'concrete_grade_mpa\']}</b><br>"\n            f"Capacity {site[\'capacity_liters\']/1000:.0f} kL · staging {site[\'staging_height_m\']:.0f} m<br>"\n            f"Tank dia {out.internal_diameter_m:.2f} m · column dia {out.staging_column_diameter_mm:.0f} mm<br>"\n            f"Concrete {out.concrete_volume_m3:.1f} m3 · relative cost {cost:.0f}<br>"\n            f"Governing lateral case: {out.governing_lateral_case}<br>"\n            f"Extra load per column: {out.staging_extra_axial_per_column_kn:.0f} kN<br>"\n            f"Foundation: {out.foundation_type}"\n        )\n\n    fig = go.Figure()\n    for tr in all_traces:\n        for t in tr:\n            fig.add_trace(t)\n    total = sum(counts)\n\n    buttons = []\n    start = 0\n    for i, cnt in enumerate(counts):\n        vis = [False] * total\n        for j in range(start, start + cnt):\n            vis[j] = True\n        buttons.append(dict(\n            label=labels[i], method="update",\n            args=[{"visible": vis},\n                  {"annotations": [dict(text=notes[i], x=0.01, y=0.99, xref="paper", yref="paper",\n                                        showarrow=False, align="left", xanchor="left", yanchor="top",\n                                        bgcolor="rgba(255,255,255,0.85)", bordercolor="#999",\n                                        borderpad=8, font=dict(size=13, color="#222")), FOOTNOTE]}]))\n        start += cnt\n\n    for j in range(total):\n        fig.data[j].visible = j < counts[0]\n\n    fig.update_layout(\n        title=dict(text="Intze tank - Pareto-optimal designs (select a design in the dropdown)",\n                   font=dict(size=16, color="#222")),\n        paper_bgcolor="white", showlegend=False,\n        scene=dict(aspectmode="data", xaxis=dict(visible=False), yaxis=dict(visible=False),\n                   zaxis=dict(title="height (m)", backgroundcolor="white", gridcolor="#ddd"),\n                   bgcolor="white", camera=dict(eye=dict(x=1.6, y=1.6, z=0.7))),\n        updatemenus=[dict(buttons=buttons, direction="down", x=0.99, xanchor="right",\n                          y=1.0, yanchor="top", bgcolor="white", font=dict(color="#222"))],\n        annotations=[dict(text=notes[0], x=0.01, y=0.99, xref="paper", yref="paper", showarrow=False,\n                          align="left", xanchor="left", yanchor="top", bgcolor="rgba(255,255,255,0.85)",\n                          bordercolor="#999", borderpad=8, font=dict(size=13, color="#222")),\n                     FOOTNOTE],\n        margin=dict(l=0, r=0, t=50, b=30), height=720,\n    )\n    return fig\n\n\ndef make_single_figure(inputs, out, cost=None):\n    """One design, no dropdown -- used by the web app\'s design detail page."""\n    traces = build_design_traces(inputs, out)\n    fig = go.Figure()\n    for t in traces:\n        fig.add_trace(t)\n    note = (f"<b>{inputs.num_columns} columns, M{inputs.concrete_grade_mpa:.0f}</b><br>"\n            f"Tank dia {out.internal_diameter_m:.2f} m - column dia {out.staging_column_diameter_mm:.0f} mm<br>"\n            f"Concrete {out.concrete_volume_m3:.1f} m3" + (f" - relative cost {cost:.0f}" if cost else "") + "<br>"\n            f"Foundation: {out.foundation_type}")\n    fig.update_layout(\n        paper_bgcolor="white", showlegend=False,\n        scene=dict(aspectmode="data", xaxis=dict(visible=False), yaxis=dict(visible=False),\n                   zaxis=dict(title="height (m)", backgroundcolor="white", gridcolor="#ddd"),\n                   bgcolor="white", camera=dict(eye=dict(x=1.6, y=1.6, z=0.7))),\n        annotations=[dict(text=note, x=0.01, y=0.99, xref="paper", yref="paper", showarrow=False,\n                          align="left", xanchor="left", yanchor="top", bgcolor="rgba(255,255,255,0.85)",\n                          bordercolor="#999", borderpad=8, font=dict(size=13, color="#222")), FOOTNOTE],\n        margin=dict(l=0, r=0, t=10, b=30), height=640)\n    return fig\n\n\nif __name__ == "__main__":\n    import webbrowser, os\n    from optimizer import run_optimization\n\n    SITE = {"capacity_liters": 500_000, "staging_height_m": 16.0, "soil_bearing_kpa": 150.0,\n            "wind_speed_m_s": 44.0, "seismic_zone_factor": 0.16}\n    candidates = run_optimization(SITE)\n    print(f"Drawing {len(candidates)} Pareto-optimal designs...")\n    fig = make_figure(SITE, candidates)\n    fig.write_html("tank_3d.html", include_plotlyjs="directory")   # plotly.min.js saved next to the page, keeps the page itself clean\n    path = os.path.abspath("tank_3d.html")\n    print(f"Saved: {path}")\n    webbrowser.open("file:///" + path.replace("\\\\", "/"))\n',
    'regional_planner.py': '"""\nRegional planner -- from a service area to a set of designed Intze tanks.\n\nInput: zones (manual, GPS point, drawn polygon, or an uploaded CSV).\nFor each zone: population (typed, or area x density, or polygon area x\ndensity), growth rate, litres per head per day, and site data (soil\nbearing capacity, wind speed, seismic zone factor).\n\nSteps\n  1. Forecast each zone\'s population to the design year and compute its\n     daily demand and the storage it needs.\n  2. Try every way of grouping zones so that each group is served by ONE\n     tank (placed at the demand-weighted centre of the group). Groups that\n     break the service-radius limit or the maximum tank size are rejected.\n  3. Design each group\'s tank with the real engineering engine: the\n     tank capacity is rounded up to a standard size, site data is the\n     most demanding of the group (lowest soil bearing, highest wind and\n     seismic), and the design is the compromise pick of the cost-versus-\n     lateral-load trade-off (same rule as the optimizer).\n  4. Total system cost = tank structures + a fixed overhead per tank site\n     + a distribution proxy (daily demand x distance, summed over zones).\n  5. Report the cheapest arrangement, the best arrangement for each number\n     of tanks, and how sensitive the answer is to the per-tank overhead.\n\nASSUMPTIONS TO CONFIRM (all values below are editable, none are standards\nunless stated):\n  - Storage = 1/3 of daily demand (typical balancing storage guidance for\n    intermittent supply); fire/emergency reserve NOT included.\n  - Design period 30 years, geometric population growth.\n  - Staging height from a placeholder hydraulic rule (12 m + 2 m per km to\n    the farthest zone, 12-24 m) -- to be replaced by a real hydraulic\n    analysis.\n  - Per-tank site overhead and the distribution cost per (ML/day x km) are\n    ILLUSTRATIVE relative-cost numbers, not rate-card values; the\n    sensitivity table shows how much the answer depends on them.\n  - Tank at the weighted centre of its group; straight-line distances, with\n    a 0.5 km minimum (local distribution inside a zone).\n  - Tank structure cost scales almost linearly with capacity in the engine,\n    so merging zones saves little structure cost; consolidation is driven\n    by the per-tank overhead -- read the sensitivity table, not one number.\n"""\n\nimport csv\nimport math\nimport sys\nimport time\n\nfrom models import DesignInputs\nfrom intze_design_engine import design_intze_tank\nfrom cost_model import total_relative_cost\nfrom location_input import polygon_area_km2, gps_distance_km\n\n# ---- editable assumptions ----\nDESIGN_YEARS = 30\nSTORAGE_FRACTION = 1.0 / 3.0\nSTANDARD_CAPACITIES_KL = [50, 100, 150, 200, 250, 300, 400, 500, 600, 750, 1000, 1250, 1500, 2000]\nMAX_SERVICE_RADIUS_KM = 2.5\nSITE_OVERHEAD = 20.0          # relative cost units per tank site\nDIST_COST_PER_ML_KM = 8.0     # relative cost units per (ML/day x km)\nINTRA_ZONE_KM = 0.5           # minimum effective distribution distance (local mains inside a zone)\nHD_RATIO = 0.9                # same baseline as the dataset / surrogate\nMAX_ZONES_EXACT = 8\n\nCOLUMN_OPTIONS = [6, 8, 10, 12]\nGRADE_OPTIONS = [20, 25, 30, 35, 40]\n\n\n# ------------------------------------------------------------------ zones\ndef _f(v, default=None):\n    v = (v or "").strip()\n    return float(v) if v else default\n\n\ndef load_zones(path):\n    with open(path, newline="", encoding="utf-8-sig") as f:\n        return load_zones_from_reader(f)\n\n\ndef load_zones_from_text(text):\n    """Same as load_zones but from CSV text (used by the web app)."""\n    import io\n    return load_zones_from_reader(io.StringIO(text.lstrip("\\ufeff")))\n\n\ndef load_zones_from_reader(f):\n    zones = []\n    if True:\n        for row in csv.DictReader(f):\n            z = {"name": row["name"].strip(), "notes": []}\n            lat, lon = _f(row.get("lat")), _f(row.get("lon"))\n            area = _f(row.get("area_km2"))\n            poly = (row.get("polygon") or "").strip()\n            if poly:\n                pts = [tuple(float(x) for x in p.split()) for p in poly.split(";")]\n                area = polygon_area_km2(pts)\n                lat = sum(p[0] for p in pts) / len(pts)\n                lon = sum(p[1] for p in pts) / len(pts)\n                z["notes"].append(f"area {area:.2f} km2 from drawn polygon")\n            if lat is None or lon is None:\n                raise ValueError(f"Zone \'{z[\'name\']}\' needs lat/lon or a polygon.")\n            pop = _f(row.get("population"))\n            if pop is None:\n                dens = _f(row.get("density_per_km2"))\n                if area is None or dens is None:\n                    raise ValueError(f"Zone \'{z[\'name\']}\' needs a population, or area and density.")\n                pop = area * dens\n                z["notes"].append(f"population = {area:.2f} km2 x {dens:.0f}/km2")\n            z.update({\n                "lat": lat, "lon": lon, "population": pop,\n                "soil": _f(row.get("soil_bearing_kpa"), 150.0),\n                "wind": _f(row.get("wind_speed_m_s"), 44.0),\n                "seismic": _f(row.get("seismic_zone_factor"), 0.16),\n                "growth": _f(row.get("growth_rate_pct"), 1.5),\n                "lpcd": _f(row.get("lpcd"), 135.0),\n            })\n            z["design_pop"] = pop * (1 + z["growth"] / 100) ** DESIGN_YEARS\n            z["demand_kl_day"] = z["design_pop"] * z["lpcd"] / 1000\n            z["storage_kl"] = z["demand_kl_day"] * STORAGE_FRACTION\n            zones.append(z)\n    return zones\n\n\n# ------------------------------------------------------------------ one tank\n_design_cache = {}\n\n\ndef design_tank(capacity_kl, staging_m, soil, wind, seismic):\n    """Compromise-pick design over (columns x grade) with the real engine."""\n    key = (capacity_kl, staging_m, round(soil), round(wind, 1), round(seismic, 3))\n    if key in _design_cache:\n        return _design_cache[key]\n    cands = []\n    for n in COLUMN_OPTIONS:\n        for g in GRADE_OPTIONS:\n            o = design_intze_tank(DesignInputs(\n                capacity_liters=capacity_kl * 1000, staging_height_m=staging_m, num_columns=n,\n                soil_bearing_capacity_kpa=soil, concrete_grade_mpa=float(g),\n                basic_wind_speed_m_s=wind, seismic_zone_factor=seismic, hd_ratio=HD_RATIO))\n            cands.append({"n": n, "grade": g,\n                          "cost": total_relative_cost(o.concrete_volume_m3, g, n, o.estimated_steel_kg),\n                          "axial": o.staging_extra_axial_per_column_kn,\n                          "col_dia": o.staging_column_diameter_mm, "foundation": o.foundation_type,\n                          "diameter": o.internal_diameter_m, "volume": o.concrete_volume_m3,\n                          "case": o.governing_lateral_case,\n                          "slender_warn": any("Slenderness" in w for w in o.warnings)})\n    front = [a for a in cands if not any(\n        b["cost"] <= a["cost"] and b["axial"] <= a["axial"] and (b["cost"] < a["cost"] or b["axial"] < a["axial"])\n        for b in cands if b is not a)]\n    cmin, cmax = min(a["cost"] for a in front), max(a["cost"] for a in front)\n    amin, amax = min(a["axial"] for a in front), max(a["axial"] for a in front)\n    def dist(a):\n        return math.hypot((a["cost"] - cmin) / ((cmax - cmin) or 1), (a["axial"] - amin) / ((amax - amin) or 1))\n    best = min(front, key=dist)\n    _design_cache[key] = best\n    return best\n\n\n# ------------------------------------------------------------------ groups\ndef set_partitions(items):\n    if not items:\n        yield []\n        return\n    first, rest = items[0], items[1:]\n    for part in set_partitions(rest):\n        for i in range(len(part)):\n            yield part[:i] + [[first] + part[i]] + part[i + 1:]\n        yield [[first]] + part\n\n\n_group_cache = {}\n\n\ndef evaluate_group(zones, idx):\n    """Cost and design of one tank serving the zones in idx (tuple of indices)."""\n    if idx in _group_cache:\n        return _group_cache[idx]\n    members = [zones[i] for i in idx]\n    w = sum(z["demand_kl_day"] for z in members)\n    lat = sum(z["lat"] * z["demand_kl_day"] for z in members) / w\n    lon = sum(z["lon"] * z["demand_kl_day"] for z in members) / w\n    dists = [gps_distance_km(lat, lon, z["lat"], z["lon"]) for z in members]\n    need = sum(z["storage_kl"] for z in members)\n    cap = next((c for c in STANDARD_CAPACITIES_KL if c >= need), None)\n    result = {"zones": idx, "lat": lat, "lon": lon, "need_kl": need, "dists": dists}\n    if cap is None:\n        result["infeasible"] = f"needs {need:.0f} kL, above the largest standard tank ({STANDARD_CAPACITIES_KL[-1]} kL)"\n    elif max(dists) > MAX_SERVICE_RADIUS_KM:\n        result["infeasible"] = f"farthest zone is {max(dists):.1f} km away (limit {MAX_SERVICE_RADIUS_KM} km)"\n    else:\n        staging = int(min(24, max(12, round(12 + 2.0 * max(dists)))))\n        d = design_tank(cap, staging, min(z["soil"] for z in members),\n                        max(z["wind"] for z in members), max(z["seismic"] for z in members))\n        result.update({"capacity_kl": cap, "staging_m": staging, "design": d,\n                       "tank_cost": d["cost"],\n                       "dist_cost": DIST_COST_PER_ML_KM * sum(z["demand_kl_day"] / 1000 * max(dd, INTRA_ZONE_KM)\n                                                              for z, dd in zip(members, dists))})\n    _group_cache[idx] = result\n    return result\n\n\ndef plan(zones):\n    _group_cache.clear()      # the cache is keyed by zone numbers only, so it must be reset for every new set of zones\n    if len(zones) > MAX_ZONES_EXACT:\n        raise SystemExit(f"{len(zones)} zones is too many for exact search (max {MAX_ZONES_EXACT}). "\n                         "Merge neighbouring zones and try again.")\n    arrangements = []\n    for part in set_partitions(list(range(len(zones)))):\n        groups = [evaluate_group(zones, tuple(sorted(g))) for g in part]\n        if any("infeasible" in g for g in groups):\n            continue\n        arrangements.append({"groups": groups, "k": len(groups),\n                             "tank_cost": sum(g["tank_cost"] for g in groups),\n                             "dist_cost": sum(g["dist_cost"] for g in groups)})\n    return arrangements\n\n\ndef total(a, overhead=None):\n    oh = SITE_OVERHEAD if overhead is None else overhead\n    return a["tank_cost"] + a["dist_cost"] + oh * a["k"]\n\n\n# ------------------------------------------------------------------ report\ndef report(zones, arrangements):\n    print("=" * 74 + "\\nREGIONAL PLAN\\n" + "=" * 74)\n    print(f"Design year: +{DESIGN_YEARS} years | storage = {STORAGE_FRACTION:.2f} x daily demand | "\n          f"max service radius {MAX_SERVICE_RADIUS_KM} km")\n    print(f"\\n{\'zone\':<14}{\'pop now\':>9}{\'pop design\':>11}{\'lpcd\':>6}{\'demand kL/d\':>12}{\'storage kL\':>11}")\n    for z in zones:\n        print(f"{z[\'name\']:<14}{z[\'population\']:>9.0f}{z[\'design_pop\']:>11.0f}{z[\'lpcd\']:>6.0f}"\n              f"{z[\'demand_kl_day\']:>12.0f}{z[\'storage_kl\']:>11.0f}")\n        for n in z["notes"]:\n            print(f"{\'\':<14}({n})")\n    tot_storage = sum(z["storage_kl"] for z in zones)\n    print(f"{\'TOTAL\':<14}{\'\':>9}{sum(z[\'design_pop\'] for z in zones):>11.0f}{\'\':>6}"\n          f"{sum(z[\'demand_kl_day\'] for z in zones):>12.0f}{tot_storage:>11.0f}")\n\n    if not arrangements:\n        print("\\nNO FEASIBLE ARRANGEMENT: no grouping satisfies the radius and tank-size limits. "\n              "Increase the service radius, allow bigger tanks, or add zones.")\n        return None\n\n    best = min(arrangements, key=total)\n    print(f"\\n--- Cheapest arrangement: {best[\'k\']} tank(s), total relative cost {total(best):.0f} ---")\n    print(f"    (tank structures {best[\'tank_cost\']:.0f} + site overhead {SITE_OVERHEAD * best[\'k\']:.0f} "\n          f"+ distribution proxy {best[\'dist_cost\']:.0f})")\n    for i, g in enumerate(sorted(best["groups"], key=lambda g: g["zones"]), 1):\n        d = g["design"]\n        names = ", ".join(zones[j]["name"] for j in g["zones"])\n        print(f"\\n  Tank {i}: {g[\'capacity_kl\']} kL at {g[\'lat\']:.4f}, {g[\'lon\']:.4f}   serves: {names}")\n        print(f"    needs {g[\'need_kl\']:.0f} kL | staging {g[\'staging_m\']} m | farthest zone "\n              f"{max(g[\'dists\']):.2f} km")\n        print(f"    design: {d[\'n\']} columns, M{d[\'grade\']}, column dia {d[\'col_dia\']:.0f} mm, "\n              f"tank dia {d[\'diameter\']:.1f} m, {d[\'foundation\']}, lateral load {d[\'axial\']:.0f} kN/column "\n              f"({d[\'case\']} governs), concrete {d[\'volume\']:.0f} m3")\n        if d["slender_warn"]:\n            print("    WARNING: column slenderness limit exceeded -- add bracing tiers before use")\n\n    print("\\nBest arrangement for each number of tanks:")\n    print(f"  {\'tanks\':>5} {\'total\':>8} {\'structures\':>11} {\'overhead\':>9} {\'distribution\':>13}")\n    for k in sorted({a["k"] for a in arrangements}):\n        a = min((x for x in arrangements if x["k"] == k), key=total)\n        mark = "  <-- cheapest" if a is best else ""\n        print(f"  {k:>5} {total(a):>8.0f} {a[\'tank_cost\']:>11.0f} {SITE_OVERHEAD * k:>9.0f} {a[\'dist_cost\']:>13.0f}{mark}")\n\n    print("\\nSensitivity: how many tanks are cheapest as the per-tank site overhead changes")\n    print("  (overhead is an illustrative number -- this shows how much the answer depends on it)")\n    prev = None\n    for oh in [0, 10, 20, 40, 80, 160, 320]:\n        b = min(arrangements, key=lambda a: total(a, oh))\n        print(f"  overhead {oh:>4}: {b[\'k\']} tank(s), total {total(b, oh):.0f}")\n    return best\n\n\ndef save_outputs(zones, best):\n    with open("regional_plan.csv", "w", newline="") as f:\n        w = csv.writer(f)\n        w.writerow(["tank", "capacity_kl", "lat", "lon", "serves", "staging_m", "columns", "grade_M",\n                    "column_dia_mm", "foundation", "lateral_kn_per_column", "concrete_m3", "relative_cost"])\n        for i, g in enumerate(sorted(best["groups"], key=lambda g: g["zones"]), 1):\n            d = g["design"]\n            w.writerow([i, g["capacity_kl"], round(g["lat"], 5), round(g["lon"], 5),\n                        "; ".join(zones[j]["name"] for j in g["zones"]), g["staging_m"], d["n"], d["grade"],\n                        round(d["col_dia"]), d["foundation"], round(d["axial"]), round(d["volume"], 1),\n                        round(d["cost"], 1)])\n    try:\n        import plotly.graph_objects as go\n        fig = go.Figure()\n        for g in best["groups"]:\n            for j in g["zones"]:\n                z = zones[j]\n                fig.add_trace(go.Scattermap(lat=[g["lat"], z["lat"]], lon=[g["lon"], z["lon"]], mode="lines",\n                                            line=dict(width=2, color="#888"), hoverinfo="skip", showlegend=False))\n        fig.add_trace(go.Scattermap(\n            lat=[z["lat"] for z in zones], lon=[z["lon"] for z in zones], mode="markers+text",\n            text=[z["name"].replace("DEMO ", "") for z in zones], textposition="bottom center",\n            marker=dict(size=[max(10, min(40, z["demand_kl_day"] / 40)) for z in zones], color="#2b7de9", opacity=0.75),\n            hovertext=[f"{z[\'name\']}<br>design population {z[\'design_pop\']:.0f}<br>storage {z[\'storage_kl\']:.0f} kL"\n                       for z in zones], hoverinfo="text", name="Zones"))\n        fig.add_trace(go.Scattermap(\n            lat=[g["lat"] for g in best["groups"]], lon=[g["lon"] for g in best["groups"]], mode="markers+text",\n            text=[f"{g[\'capacity_kl\']} kL" for g in best["groups"]], textposition="top center",\n            marker=dict(size=22, color="#e23b3b", symbol="circle"),\n            hovertext=[f"Tank {g[\'capacity_kl\']} kL, staging {g[\'staging_m\']} m, "\n                       f"{g[\'design\'][\'n\']} columns M{g[\'design\'][\'grade\']}" for g in best["groups"]],\n            hoverinfo="text", name="Tanks"))\n        fig.update_layout(map=dict(style="open-street-map",\n                                   center=dict(lat=sum(z["lat"] for z in zones) / len(zones),\n                                               lon=sum(z["lon"] for z in zones) / len(zones)), zoom=12.5),\n                          margin=dict(l=0, r=0, t=40, b=0), height=700,\n                          title=f"Regional plan: {best[\'k\']} tank(s) (zones blue, tanks red)")\n        fig.write_html("regional_map.html", include_plotlyjs="directory")\n        save_plain_map(zones, best)\n        print("\\nSaved: regional_plan.csv, regional_map_plain.html, regional_map.html (street map, needs internet)")\n    except Exception as e:                                   # map is a bonus; never block the plan\n        print(f"\\nSaved: regional_plan.csv  (map skipped: {e})")\n\n\ndef save_plain_map(zones, best):\n    """Offline map (no tiles needed): zones, tanks and service links on lat/lon axes."""\n    fig = build_plain_map_figure(zones, best)\n    fig.write_html("regional_map_plain.html", include_plotlyjs="directory")   # keeps the page itself clean\n\n\ndef build_plain_map_figure(zones, best):\n    import plotly.graph_objects as go\n    fig = go.Figure()\n    for g in best["groups"]:\n        for j in g["zones"]:\n            z = zones[j]\n            fig.add_trace(go.Scatter(x=[g["lon"], z["lon"]], y=[g["lat"], z["lat"]], mode="lines",\n                                     line=dict(width=2, color="#9aa0a6"), hoverinfo="skip", showlegend=False))\n    fig.add_trace(go.Scatter(\n        x=[z["lon"] for z in zones], y=[z["lat"] for z in zones], mode="markers+text",\n        text=[z["name"].replace("DEMO ", "") for z in zones], textposition="bottom center",\n        marker=dict(size=[max(14, min(46, z["demand_kl_day"] / 35)) for z in zones], color="#2b7de9", opacity=0.75),\n        hovertext=[f"{z[\'name\']}<br>design population {z[\'design_pop\']:.0f}<br>storage {z[\'storage_kl\']:.0f} kL"\n                   for z in zones], hoverinfo="text", name="Zones (size = demand)"))\n    fig.add_trace(go.Scatter(\n        x=[g["lon"] for g in best["groups"]], y=[g["lat"] for g in best["groups"]], mode="markers+text",\n        text=[f"{g[\'capacity_kl\']} kL" for g in best["groups"]], textposition="top center",\n        marker=dict(size=20, color="#e23b3b", symbol="star"),\n        hovertext=[f"Tank {g[\'capacity_kl\']} kL, staging {g[\'staging_m\']} m, {g[\'design\'][\'n\']} columns "\n                   f"M{g[\'design\'][\'grade\']}" for g in best["groups"]], hoverinfo="text", name="Tanks"))\n    mean_lat = sum(z["lat"] for z in zones) / len(zones)\n    fig.update_layout(\n        title=f"Regional plan: {best[\'k\']} tank(s)  (blue = zones, red stars = tanks, grey = service links)",\n        xaxis=dict(title="longitude", showgrid=True, gridcolor="#e6e6e6"),\n        yaxis=dict(title="latitude", showgrid=True, gridcolor="#e6e6e6",\n                   scaleanchor="x", scaleratio=1 / math.cos(math.radians(mean_lat))),\n        plot_bgcolor="white", paper_bgcolor="white", height=700, margin=dict(l=60, r=20, t=60, b=50))\n    return fig\n\n\nif __name__ == "__main__":\n    path = sys.argv[1] if len(sys.argv) > 1 else "zones_demo.csv"\n    t0 = time.time()\n    zones = load_zones(path)\n    arrangements = plan(zones)\n    best = report(zones, arrangements)\n    if best:\n        save_outputs(zones, best)\n    print(f"\\n(computed in {time.time() - t0:.0f} s)")\n',
    'test_app.py': '"""Automated checks for the web app: logins, role permissions, input checks and a\nscan that no page points to an outside website.  Run:  python test_app.py"""\nimport re\nimport app as A\n\npassed = failed = 0\n\n\ndef check(name, ok):\n    global passed, failed\n    passed += ok\n    failed += (not ok)\n    print(("PASS  " if ok else "FAIL  ") + name)\n\n\ndef client(user=None, pw=None):\n    c = A.app.test_client()\n    with c.session_transaction() as s:\n        s["csrf"] = "t"\n    if user:\n        c.post("/login", data={"csrf": "t", "username": user, "password": pw})\n        with c.session_transaction() as s:\n            s["csrf"] = "t"\n    return c\n\n\nDETAIL = ("/design/detail?capacity_kl=500&staging_height_m=16&soil_bearing_kpa=150&wind_speed_m_s=44"\n          "&seismic_zone_factor=0.16&num_columns=8&grade=20")\n\n# --- not signed in: everything redirects to login\nanon = client()\nfor url in ["/overview", "/design", DETAIL, "/regional", "/vendor/plotly.js", "/advice"]:\n    r = anon.get(url)\n    check(f"signed-out {url[:22]} -> login", r.status_code == 302 and "/login" in r.headers["Location"])\n\n# --- wrong password\nbad = client("manager", "wrong")\ncheck("wrong password rejected", bad.get("/overview").status_code == 302)\n\n# --- every role can view the read-only pages\nfor u, p in [("manager", "Manager@123"), ("site", "Site@123"), ("client", "Client@123")]:\n    c = client(u, p)\n    for url in ["/design", DETAIL, "/regional"]:\n        check(f"{u} can open {url[:22]}", c.get(url).status_code == 200)\n\n# --- design detail content and input checks\nc = client("client", "Client@123")\nh = c.get(DETAIL).data.decode()\ncheck("detail shows foundation load", "Load on foundation" in h)\ncheck("detail lists assumptions", "Assumptions used for this design" in h)\ncheck("detail rejects text input", c.get("/design/detail?capacity_kl=abc").status_code == 302)\ncheck("detail rejects out-of-range input", c.get(DETAIL.replace("capacity_kl=500", "capacity_kl=999999")).status_code == 302)\ncheck("detail rejects odd grade", c.get(DETAIL.replace("grade=20", "grade=22")).status_code == 302)\n\n# --- regional planner\nr = c.post("/regional", data={"csrf": "t", "zones": A.DEMO_ZONES_CSV})\ncheck("regional plans demo zones", b"Cheapest arrangement" in r.data)\nr = c.post("/regional", data={"csrf": "t", "zones": "name,lat\\nX,abc"})\ncheck("regional survives bad CSV", r.status_code == 200 and b"Could not read" in r.data)\nr = c.post("/regional", data={"csrf": "bad", "zones": A.DEMO_ZONES_CSV})\ncheck("regional POST needs CSRF token", r.status_code in (400, 403))\n\n# --- role limits on actions\ncl = client("client", "Client@123")\ncheck("client cannot log progress (needs \'log\')", cl.post("/progress", data={"csrf": "t"}).status_code in (302, 403))\nsm = client("manager", "Manager@123")\ncheck("signed-out POST without token is refused", client().post("/progress", data={}).status_code == 400)\n\n# --- no outside links or GitHub text in any page\npages = [c.get("/design").data, c.get(DETAIL).data, c.post("/regional", data={"csrf": "t", "zones": A.DEMO_ZONES_CSV}).data,\n         c.get("/overview").data]\noutside = set()\nfor p in pages:\n    outside |= set(re.findall(rb"(?:src|href)=[\\"\']https?://[^\\"\']+", p))\ncheck("no outside links in pages (" + str(len(outside)) + " found)", not outside)\ncheck("no \'github\' text in pages", all(b"github" not in p.lower() for p in pages))\n\nprint(f"\\n{passed} passed, {failed} failed")\nraise SystemExit(1 if failed else 0)\n',
}
ROOT_FILES = {
    'README.md': "# Intze Tank Platform\n\nAI-driven parametric design and multi-tank optimisation of Intze elevated water tanks, built to work **with** the civil\nengineer from the first sizing to the as-built check. B.Tech major project, Zainab Nayeem, SMIT (AI&DS).\nCredits, libraries and originality statement: see [THIRD_PARTY.md](THIRD_PARTY.md).\n\n## What it does\n| Part | File | What it gives |\n|---|---|---|\n| Design engine | `src/intze_design_engine.py` | Geometry, wall, dome and cone members, staging columns, foundation, concrete and steel quantities for one tank |\n| Validation | `src/validate_engine.py` | 68 checks: independent load-path check, trends, comparison with published optimum H/D |\n| ML surrogate | `src/generate_dataset.py`, `src/train_surrogate.py` | Fast predictions trained on 20,000 designs made by the engine itself (synthetic data) |\n| Optimiser | `src/optimizer.py` | NSGA-II over columns and grade; candidates are re-computed on the real engine |\n| Adaptive re-optimiser | `src/adaptive_reoptimizer.py` | Re-plans when stock, budget or site limits change |\n| Construction tracker | `src/construction_tracker.py` | Stage locks, stock, minimal-change options, as-built check |\n| Regional planner | `src/regional_planner.py` | Demand forecast, storage, best grouping of zones into tanks |\n| Web app | `src/app.py` | Roles, project pages, design options, 3D view, printable summary, regional planner |\n\n## Run it (Windows CMD, from the `src` folder)\n```\npip install numpy pandas scikit-learn joblib pymoo plotly flask\npython generate_dataset.py\npython train_surrogate.py\npython validate_engine.py\npython app.py\n```\nOpen http://127.0.0.1:5000 . Demo accounts (change before any real use):\n\n| User | Password | Role | Can |\n|---|---|---|---|\n| manager | Manager@123 | Manager | everything, including accepting a design |\n| site | Site@123 | Site engineer | log progress, stock and site data |\n| client | Client@123 | Client | view only |\n\n## Pages\n- **Overview / Site desk / Advice**: project state, stage progress, stock, and the tracker's advice when something changes.\n- **Design**: enter capacity and site values, get the Pareto options (cost against load on columns), each with a **Details and 3D** page.\n- **Design details**: full engine output, warnings, assumptions, a 3D model and a print / save-as-PDF button.\n- **Regional**: paste a zone list (CSV), get the cheapest grouping of zones into tanks, a map and a sensitivity table.\n\n## Test\n```\npython test_app.py\n```\nChecks login, role limits, CSRF, input validation, and that no page links to an outside website.\n\n## Honest limits\nRelative costs only; wind and seismic by simplified static methods; ring beam, cone, raft and bracing use placeholder rules;\nno live load; not yet compared with a real project or the original VB5 tool. Decision-support only: a licensed structural\nengineer must check and sign off any design.\n",
    'THIRD_PARTY.md': "# Credits, tools and originality statement\n\n**Project:** AI-Driven Parametric Design and Multi-Tank Optimisation of Intze Elevated Water Tanks\n**Author:** Zainab Nayeem (SMIT, AI&DS, enrolment 202300069)\n\n## What is original work in this repository\nAll project code in `src/` was written for this project and is not copied from any other repository:\ndesign engine (`intze_design_engine.py`, `wall_design.py`, `staging_design.py`, `foundation_design.py`, `wind_seismic.py`),\ncost model, dataset generator, surrogate training, optimiser wrapper, adaptive re-optimiser, construction tracker,\nregional planner, 3D visualisation script, validation script, tests, and the Flask web app (`app.py`, `templates/`, `static/`).\nThe training data is synthetic, generated by this project's own design engine (`generate_dataset.py`).\n\n## Open-source libraries used (installed with pip, not copied into the code)\n| Library | Used for | Licence |\n|---|---|---|\n| NumPy, pandas | numerical work, tables | BSD |\n| scikit-learn | gradient-boosting surrogate models | BSD |\n| joblib | saving/loading trained models | BSD |\n| pymoo (Blank & Deb, 2020) | NSGA-II multi-objective search | Apache-2.0 |\n| Plotly | 3D tank and regional map charts | MIT |\n| Flask, Werkzeug | web application, password hashing | BSD |\n\n**Plotly.js (the chart library) and how it is delivered.** The charts are drawn by Plotly.js, which is not project code.\nIt is **not stored in this repository**. The web app serves it from the installed `plotly` package when a page is opened,\nand the stand-alone chart scripts save it next to their output as `plotly.min.js` (ignored by git). The pages written by this\nproject therefore contain only project content. The Plotly.js file itself, if opened, carries the notices of the open-source\nlibraries inside it (for example d3 and maplibre-gl); that is Plotly's code, not project code.\nThe optional street-map file (`regional_map.html`) loads OpenStreetMap tiles from the internet (© OpenStreetMap contributors);\nthe web app does not use it. The web app uses system fonts and loads nothing from other websites (checked by `test_app.py`).\n\n## Engineering sources (formulas and rules, not code)\n- IS 3370 (liquid-retaining structures), IS 456:2000 (reinforced concrete), IS 875 Part 3 (wind), IS 1893 Part 1 (seismic).\n  Simplified static methods are used and the assumptions are logged in each design output.\n- Literature: Saxena & Pathak (2024), Indian Journal of Engineering and Materials Sciences 31(5); Intze shape-optimisation\n  papers (Univ. of Tabriz 2015; meta-heuristic study 2024); Deb et al. (2002), NSGA-II; Blank & Deb (2020), pymoo.\n  Papers were read at abstract level so far.\n\n## Inspiration (no code taken)\n- The idea of an Intze design tool comes from a Visual Basic 5 program written earlier by the author's father.\n  Its source code has not been used or seen in this project.\n- The dark visual style of the web app follows a reference image of a website supplied by the author. No code or assets were copied.\n\n## Honest limits\nCosts are relative (illustrative), wind and seismic use simplified static methods, the ring beam uses a placeholder rule,\nand the engine has not yet been compared with the VB5 program or with a real project. This is a decision-support tool,\nnot a replacement for a licensed structural engineer.\n",
}
IGNORE = ['__pycache__/', '*.pyc', 'backup_v04/', 'backup_v05/', 'project_state.json', '*.joblib', 'plotly.min.js', 'tank_3d.html', 'regional_map.html', 'regional_map_plain.html', 'regional_plan.csv', 'adaptive_log.csv', 'validation_report.csv']

os.makedirs("backup_v05", exist_ok=True)
for path, text in FILES.items():
    folder = os.path.dirname(path)
    if folder:
        os.makedirs(folder, exist_ok=True)
        os.makedirs(os.path.join("backup_v05", folder), exist_ok=True)
    if os.path.exists(path):
        shutil.copy2(path, os.path.join("backup_v05", path))
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
    print("written:", path)
for name, text in ROOT_FILES.items():
    with open(os.path.join("..", name), "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
    print("written: ..\\" + name)
gi = os.path.join("..", ".gitignore")
have = open(gi, encoding="utf-8").read().split() if os.path.exists(gi) else []
add = [x for x in IGNORE if x not in have]
with open(gi, "a", encoding="utf-8", newline="\n") as f:
    if add:
        f.write("\n" + "\n".join(add) + "\n")
print("updated: ..\\.gitignore (" + str(len(add)) + " lines added)")
